import { Slider } from '@refy-design/web';
import type { ComponentProps } from 'react';
import { useState } from 'react';
export function Example() {
  const args: Pick<ComponentProps<typeof Slider>, 'label'> = { label: 'Depth' };
  const [v, setV] = useState(50);
  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
      <Slider {...args} value={v} onChange={setV} formatValue={(x) => `${x}%`} />
      <code
        style={{ fontFamily: 'var(--font-mono)', fontSize: 12, color: 'var(--ink-3)' }}
      >
        value: {v}
      </code>
    </div>
  );
}

